contract InvMutTest {
    C c;
    address lastTo;

    constructor(C _c) { c = _c; }

    fallback() external {
        assembly {
            mstore(0, shr(96, calldataload(36)))
        }
        lastTo = address(uint160(uint256(bytes32(mload(0)))));
    }

    function test(address _to) public {
        address[] memory tos = new address[](1);
        tos[0] = _to;
        uint[] memory vs = new uint[](1);
        vs[0] = 1;
        lastTo = address(0);
        bool ok = c.transfer(address(this), address(this), tos, vs);
        assert(ok && lastTo == _to);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == 1 && v.length == 1);
        bool reverted;
        try c.transfer(from, address(this), _tos, v) { reverted = false; } catch { reverted = true; }
        // The original always executes the (reverting) transferFrom call for the single
        // recipient, so transfer reverts; the mutant skips it and returns true.
        assert(reverted);
    }
    fallback() external payable {
        revert();
    }
}

contract InvMutTest {
    C c;
    uint public calls;

    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        require(_tos.length > 0);
        bool allSelf = true;
        for (uint i = 0; i < _tos.length; i++) {
            if (_tos[i] != address(this)) { allSelf = false; }
        }
        require(allSelf);
        calls = 0;
        bool reverted;
        try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(calls == _tos.length);
    }

    fallback() external payable {
        calls++;
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    address lastTo;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint[] memory v) public {
        require(_tos.length > 0 && _tos.length == v.length);
        lastTo = _tos[_tos.length - 1];
        bool reverted;
        try c.transfer(from, address(this), _tos, v) { reverted = false; } catch { reverted = true; }
        // Rule: with a token that reverts exactly on transfers to the last
        // recipient, transfer must revert (the last transferFrom is attempted).
        assert(reverted);
    }

    fallback() external {
        if (msg.data.length == 4 + 96) {
            (, address to, ) = abi.decode(msg.data[4:], (address, address, uint256));
            if (to == lastTo) revert();
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Fallback (token caddress): accepts transferFrom only when the value
    // argument (last 32 bytes of calldata) is zero; otherwise reverts.
    fallback() external payable {
        uint val;
        if (msg.data.length >= 32) {
            val = abi.decode(msg.data[msg.data.length - 32:], (uint));
        }
        require(val == 0);
    }
    receive() external payable {}

    function run(address from, uint[] memory v) public payable {
        address to = address(this);
        address[] memory tos = new address[](2);
        tos[0] = to;
        tos[1] = to;
        require(v.length == 2);
        require(v[0] == 0);
        require(v[1] != 0);
        bool reverted;
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        // First call succeeds (v[0]==0), last call must be attempted and reverts (v[1]!=0).
        assert(reverted);
    }
}
